import { describe, expect, it } from "vitest";
import { optimizeSvg, optimizeSvgWithStats, resolveSvgOptions } from "../src/optimize.js";
import * as pkg from "../src/index.js";

const BLOATED = `<?xml version="1.0" encoding="UTF-8"?>
<!-- generated by a design tool -->
<svg xmlns="http://www.w3.org/2000/svg" width="100" height="100">
  <title>Test</title>
  <g id="layer-one">
    <rect id="hero-rect" x="0" y="0" width="100.000" height="100" fill="#ff0000"/>
  </g>
</svg>`;

describe("resolveSvgOptions", () => {
  it("defaults to preset-default with multipass on", () => {
    const config = resolveSvgOptions();
    expect(config.multipass).toBe(true);
    expect(config.plugins).toEqual(["preset-default"]);
  });

  it("preserveIds disables cleanupIds via preset overrides", () => {
    const config = resolveSvgOptions({ preserveIds: true });
    expect(config.plugins).toEqual([
      { name: "preset-default", params: { overrides: { cleanupIds: false } } },
    ]);
  });

  it("a full plugin list replaces the preset untouched", () => {
    const config = resolveSvgOptions({ plugins: ["removeDoctype"], preserveIds: true });
    expect(config.plugins).toEqual(["removeDoctype"]);
  });
});

describe("optimizeSvg (real SVGO)", () => {
  it("strips comments/xml prolog and shrinks the file", () => {
    const out = optimizeSvg(BLOATED);
    expect(out).not.toContain("<!--");
    expect(out).not.toContain("<?xml");
    expect(out.length).toBeLessThan(BLOATED.length);
    expect(out).toContain("<svg");
  });

  it("preserveIds keeps referenced ids intact", () => {
    const out = optimizeSvg(BLOATED, { preserveIds: true });
    expect(out).toContain('id="hero-rect"');
    expect(out).toContain('id="layer-one"');
  });

  it("rejects empty input", () => {
    expect(() => optimizeSvg("   ")).toThrow(RangeError);
  });

  it("reports byte stats", () => {
    const r = optimizeSvgWithStats(BLOATED);
    expect(r.outputBytes).toBe(new TextEncoder().encode(r.svg).length);
    expect(r.outputBytes).toBeLessThan(r.originalBytes);
    expect(r.savingsRatio).toBeGreaterThan(0);
  });
});

describe("public surface", () => {
  it("exports the documented entry points", () => {
    expect(typeof pkg.optimizeSvg).toBe("function");
    expect(typeof pkg.optimizeSvgWithStats).toBe("function");
    expect(typeof pkg.resolveSvgOptions).toBe("function");
  });
});
